\section*{Cyclic Stochastic Gradient Descent (Cyclic SGD)}

\section*{Mathematical Formulation}
Let $f:\mathbb{R}^d\rightarrow\mathbb{R}$ be the objective function and let $\{z_t\}_{t\ge 0}$ be an i.i.d. data stream.
At iteration $t$ a stochastic gradient 
\[
g_t\;:=\;\nabla f(w_t;z_t)
\]
is computed.  
The learning rate follows a \emph{triangular cyclic schedule} with period $M\in\mathbb{N}$,
minimum step size $\eta_{\min}>0$ and maximum step size $\eta_{\max}>\eta_{\min}$:
\[
\eta_t \;=\;
\begin{cases}
\displaystyle 
\eta_{\min}+ \frac{2(\eta_{\max}-\eta_{\min})}{M}\,t \quad & 0\le t <\frac{M}{2},\\[6pt]
\displaystyle 
\eta_{\max}- \frac{2(\eta_{\max}-\eta_{\min})}{M}\,\Bigl(t-\frac{M}{2}\Bigr) \quad & \frac{M}{2}\le t < M,
\end{cases}
\tag{1}
\]
and the pattern repeats every $M$ steps, i.e. $\eta_{t+M}=\eta_t$.

The update rule is
\[
w_{t+1}=w_t-\eta_t\,g_t,\qquad t=0,1,2,\dots .
\tag{2}
\]

\section*{Pseudocode}
\begin{algorithm}[H]
\caption{Cyclic SGD}
\begin{algorithmic}[1]
\REQUIRE Initial point $w_0\in\mathbb{R}^d$, period $M$, $\eta_{\min},\eta_{\max}$, number of iterations $T$.
\FOR{$t=0$ \TO $T-1$}
    \STATE Compute stochastic gradient $g_t=\nabla f(w_t;z_t)$.
    \STATE Compute learning rate $\eta_t$ according to (1).
    \STATE Update $w_{t+1}=w_t-\eta_t g_t$.
\ENDFOR
\RETURN $w_T$ (or optionally the average $\bar w_T=\frac1T\sum_{t=0}^{T-1}w_t$).
\end{algorithmic}
\end{algorithm}

\section*{Dry Run Example}
Consider the scalar quadratic $f(w)=(w-3)^2$, thus $\nabla f(w)=2(w-3)$.
Choose $w_0=0$, $M=4$, $\eta_{\min}=0.05$, $\eta_{\max}=0.15$, and run three iterations.

\begin{enumerate}
\item \textbf{Iteration $t=0$:} 
\[
\eta_0=\eta_{\min}=0.05,\qquad
g_0=2(w_0-3)=2(0-3)=-6.
\]
Update:
\[
w_1=w_0-\eta_0 g_0=0-0.05(-6)=0.30.
\]
Objective:
\[
f(w_1)=(0.30-3)^2=7.29.
\]

\item \textbf{Iteration $t=1$:} 
\[
\eta_1=\eta_{\min}+ \frac{2(\eta_{\max}-\eta_{\min})}{M}\cdot1
       =0.05+ \frac{2(0.10)}{4}=0.10,
\]
\[
g_1=2(w_1-3)=2(0.30-3)=-5.40.
\]
Update:
\[
w_2=w_1-\eta_1 g_1=0.30-0.10(-5.40)=0.84.
\]
Objective:
\[
f(w_2)=(0.84-3)^2=4.66.
\]

\item \textbf{Iteration $t=2$:} 
\[
\eta_2=\eta_{\max}=0.15,
\]
\[
g_2=2(w_2-3)=2(0.84-3)=-4.32.
\]
Update:
\[
w_3=w_2-\eta_2 g_2=0.84-0.15(-4.32)=1.50.
\]
Objective:
\[
f(w_3)=(1.50-3)^2=2.25.
\]
\end{enumerate}
The example demonstrates decreasing objective values while the step size cycles.

\newpage
\section*{Assumptions}
\begin{assumption}[Smoothness]\label{as:smooth}
$f$ is $L$‑smooth: for all $x,y\in\mathbb{R}^d$,
\[
f(y)\le f(x)+\langle\nabla f(x),y-x\rangle+\frac{L}{2}\|y-x\|^2 .
\]
\end{assumption}
\begin{assumption}[Bounded Variance]\label{as:var}
For every $w$, the stochastic gradient satisfies
\[
\mathbb{E}[g_t\mid w_t]=\nabla f(w_t),\qquad
\mathbb{E}\big[\|g_t-\nabla f(w_t)\|^2\mid w_t\big]\le\sigma^2 .
\]
\end{assumption}
\begin{assumption}[Bounded Gradient]\label{as:grad}
There exists $G>0$ such that $\|\nabla f(w)\|\le G$ for all $w$.
\end{assumption}
\begin{assumption}[Learning‑rate bounds]\label{as:lr}
The cyclic schedule satisfies
\[
0<\eta_{\min}\le\eta_t\le\eta_{\max},\qquad\forall t,
\]
and the period $M$ is a fixed positive integer.
\end{assumption}

\section*{Main Convergence Theorem}
\begin{theorem}\label{thm:main}
Assume \ref{as:smooth}–\ref{as:lr} hold and let $w^*$ be a global minimizer of $f$.
Define $T$ total iterations and $\bar w_T:=\frac1T\sum_{t=0}^{T-1}w_t$.
Then
\[
\frac1T\sum_{t=0}^{T-1}\mathbb{E}\big[\|\nabla f(w_t)\|^2\big]
\;\le\;
\frac{2\big(f(w_0)-f(w^*)\big)}{\eta_{\min}T}
\;+\;
L\eta_{\max}\sigma^2 .
\tag{3}
\]
Consequently, if we choose $\eta_{\max}=O\!\left(\frac{1}{\sqrt{T}}\right)$ while keeping the ratio
$\eta_{\max}/\eta_{\min}=c$ constant, we obtain
\[
\frac1T\sum_{t=0}^{T-1}\mathbb{E}\big[\|\nabla f(w_t)\|^2\big]=O\!\left(\frac{1}{\sqrt{T}}\right).
\]
\end{theorem}

\section*{Theoretical Properties}
\begin{enumerate}
\item \textbf{Stability.} Because every $\eta_t$ is upper bounded by $\eta_{\max}$, the standard $L$‑smooth descent lemma guarantees that the iterates remain in a bounded region provided $w_0$ is bounded.
\item \textbf{Hyper‑parameter sensitivity.} The bound \eqref{thm:main} depends on the ratio $\eta_{\max}/\eta_{\min}$ only through the constant $c=\eta_{\max}/\eta_{\min}$. Choosing $c$ too large inflates the first term of \eqref{3} via a smaller $\eta_{\min}$, while a too small $c$ reduces the benefit of occasional larger steps.
\item \textbf{Comparison to standard SGD.} For constant step size $\eta$, the classic non‑convex SGD bound is
\[
\frac1T\sum_{t=0}^{T-1}\mathbb{E}\|\nabla f(w_t)\|^2\le
\frac{2\big(f(w_0)-f(w^*)\big)}{\eta T}+L\eta\sigma^2 .
\]
Cyclic SGD replaces the constant $\eta$ by the *average* of the cycle,
\[
\bar\eta:=\frac{1}{M}\sum_{t=0}^{M-1}\eta_t=\frac{\eta_{\min}+\eta_{\max}}{2},
\]
and the bound \eqref{3} shows that the worst‑case $\eta_{\max}$ appears only in the variance term, leading to a potentially tighter guarantee when $\eta_{\max}>\bar\eta$ but $\eta_{\min}$ is not too small.
\end{enumerate}

\section*{Discussion}
The theorem demonstrates that a cyclic learning rate does not degrade the standard $O(1/\sqrt{T})$ rate for non‑convex stochastic optimization. The key insight is that the descent contribution is governed by the *minimum* step size (the most conservative update), whereas the variance amplification is controlled by the *maximum* step size. By carefully selecting $\eta_{\min}$ and $\eta_{\max}$, practitioners can obtain aggressive exploration (large $\eta_{\max}$) without sacrificing the asymptotic convergence guarantee.

\newpage
\section*{Preliminaries (Definitions and Lemmas)}
\begin{lemma}[Smoothness Descent Inequality]\label{lem:smooth}
If $f$ is $L$‑smooth, then for any $w$ and any stochastic gradient $g$,
\[
f(w-\eta g)\le f(w)-\eta\langle\nabla f(w),g\rangle+\frac{L\eta^2}{2}\|g\|^2 .
\]
\end{lemma}
\begin{proof}
Apply the definition of $L$‑smoothness with $y=w-\eta g$ and rearrange terms. \hfill $\square$
\end{proof}

\begin{lemma}[Unbiasedness and Variance Decomposition]\label{lem:variance}
For any $w$,
\[
\mathbb{E}\big[\|g-\nabla f(w)\|^2\mid w\big]=\mathbb{E}\big[\|g\|^2\mid w\big]-\|\nabla f(w)\|^2 .
\]
\end{lemma}
\begin{proof}
Straightforward expansion of $\|g\|^2=\|g-\nabla f(w)+\nabla f(w)\|^2$ and use $\mathbb{E}[g\mid w]=\nabla f(w)$. \hfill $\square$
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem \ref{thm:main}. Throughout the proof, expectations are taken with respect to the randomness up to iteration $t$ (i.e., conditioning on $w_t$).

\begin{enumerate}
\item[Step 1.] Apply Lemma \ref{lem:smooth} with $w=w_t$, $g=g_t$, and $\eta=\eta_t$:
\[
f(w_{t+1})\le f(w_t)-\eta_t\langle\nabla f(w_t),g_t\rangle+\frac{L\eta_t^{2}}{2}\|g_t\|^{2}.
\tag{4}
\]

\item[Step 2.] Take conditional expectation $\mathbb{E}[\cdot\mid w_t]$ on both sides of \eqref{4}. Using unbiasedness $\mathbb{E}[g_t\mid w_t]=\nabla f(w_t)$,
\[
\mathbb{E}\big[f(w_{t+1})\mid w_t\big]\le
f(w_t)-\eta_t\|\nabla f(w_t)\|^{2}
+\frac{L\eta_t^{2}}{2}\,\mathbb{E}\big[\|g_t\|^{2}\mid w_t\big].
\tag{5}
\]

\item[Step 3.] Decompose $\mathbb{E}[\|g_t\|^{2}\mid w_t]$ using Lemma \ref{lem:variance}:
\[
\mathbb{E}\big[\|g_t\|^{2}\mid w_t\big]
= \|\nabla f(w_t)\|^{2}+\mathbb{E}\big[\|g_t-\nabla f(w_t)\|^{2}\mid w_t\big]
\le \|\nabla f(w_t)\|^{2}+\sigma^{2},
\tag{6}
\]
where the inequality follows from Assumption \ref{as:var}.

\item[Step 4.] Substitute \eqref{6} into \eqref{5}:
\[
\mathbb{E}\big[f(w_{t+1})\mid w_t\big]\le
f(w_t)-\eta_t\|\nabla f(w_t)\|^{2}
+\frac{L\eta_t^{2}}{2}\big(\|\nabla f(w_t)\|^{2}+\sigma^{2}\big).
\tag{7}
\]

\item[Step 5.] Rearrange \eqref{7} to isolate the gradient term:
\[
\big(\eta_t-\tfrac{L}{2}\eta_t^{2}\big)\,\|\nabla f(w_t)\|^{2}
\;\le\;
f(w_t)-\mathbb{E}[f(w_{t+1})\mid w_t]
+\tfrac{L}{2}\eta_t^{2}\sigma^{2}.
\tag{8}
\]

\item[Step 6.] Since $0<\eta_t\le\eta_{\max}$, we have
\[
\eta_t-\tfrac{L}{2}\eta_t^{2}
\;\ge\;
\eta_{\min}-\tfrac{L}{2}\eta_{\max}^{2}
\;\ge\;
\frac{\eta_{\min}}{2},
\tag{9}
\]
provided the step sizes satisfy the standard *stability condition*
\[
\eta_{\max}\le \frac{1}{L}.
\]
In what follows we assume this condition; otherwise the bound trivially holds with a larger constant.

\item[Step 7.] Using (9) in (8) yields
\[
\frac{\eta_{\min}}{2}\,\|\nabla f(w_t)\|^{2}
\;\le\;
f(w_t)-\mathbb{E}[f(w_{t+1})\mid w_t]
+\frac{L}{2}\eta_{\max}^{2}\sigma^{2}.
\tag{10}
\]

\item[Step 8.] Take total expectation over the history up to iteration $t$ and sum \eqref{10} for $t=0,\dots,T-1$:
\[
\frac{\eta_{\min}}{2}\sum_{t=0}^{T-1}\mathbb{E}\big[\|\nabla f(w_t)\|^{2}\big]
\le
\mathbb{E}[f(w_0)]-\mathbb{E}[f(w_T)]
+ \frac{L}{2}\eta_{\max}^{2}\sigma^{2}T .
\tag{11}
\]

\item[Step 9.] Since $f(w_T)\ge f(w^*)$, we obtain
\[
\frac{\eta_{\min}}{2}\sum_{t=0}^{T-1}\mathbb{E}\big[\|\nabla f(w_t)\|^{2}\big]
\le
f(w_0)-f(w^*) + \frac{L}{2}\eta_{\max}^{2}\sigma^{2}T .
\tag{12}
\]

\item[Step 10.] Divide both sides of \eqref{12} by $T$ and by $\eta_{\min}/2$:
\[
\frac1T\sum_{t=0}^{T-1}\mathbb{E}\big[\|\nabla f(w_t)\|^{2}\big]
\le
\frac{2\big(f(w_0)-f(w^*)\big)}{\eta_{\min}T}
+ L\eta_{\max}\sigma^{2}.
\tag{13}
\]
Equation \eqref{13} is exactly the bound \eqref{3} claimed in Theorem \ref{thm:main}. \hfill $\square$
\end{enumerate}

\section*{Rate Derivation (With Constants)}
From \eqref{13}, set $\eta_{\max}=c\,\eta_{\min}$ with a fixed ratio $c>1$.
Choose $\eta_{\min}= \frac{c_0}{\sqrt{T}}$ where $c_0>0$ satisfies $c_0\le \frac{1}{L\sqrt{c}}$ to respect the stability condition.
Then
\[
\frac{2\big(f(w_0)-f(w^*)\big)}{\eta_{\min}T}
= \frac{2\big(f(w_0)-f(w^*)\big)}{c_0}\,\frac{1}{\sqrt{T}},
\qquad
L\eta_{\max}\sigma^{2}=L c\,c_0\,\frac{1}{\sqrt{T}}\sigma^{2}.
\]
Both terms decay as $O(1/\sqrt{T})$, establishing the $O(1/\sqrt{T})$ convergence rate for the average squared gradient norm.

\section*{Special Cases}
\begin{enumerate}[label=\arabic*.]
\item \textbf{Constant step size.} When $\eta_{\min}=\eta_{\max}=\eta$, the bound \eqref{13} reduces to the classic SGD bound
\[
\frac1T\sum_{t=0}^{T-1}\mathbb{E}\|\nabla f(w_t)\|^{2}
\le \frac{2(f(w_0)-f(w^*))}{\eta T}+L\eta\sigma^{2}.
\]

\item \textbf{Vanishing variance.} If $\sigma=0$ (deterministic gradients), the variance term disappears and we obtain a pure descent rate
\[
\frac1T\sum_{t=0}^{T-1}\mathbb{E}\|\nabla f(w_t)\|^{2}
\le \frac{2(f(w_0)-f(w^*))}{\eta_{\min}T}.
\]

\item \textbf{Large period $M$.} The bound \eqref{13} does not depend explicitly on $M$; however, a larger $M$ yields a slower oscillation, making the effective $\eta_{\min}$ closer to the average step size and often improving practical performance.
\end{enumerate}

